#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <cstring>
using namespace std;

const int MAXN = 200;
const int MAXM = 100000;
const int INF = 100000000;

int maze_grid[20][20];
int graph_adj[MAXN][MAXN];
int n, total_nodes, t;
string line_input;
int hu_list[MAXN][3], re_list[MAXN][3];
int zr, zc;
int cX, cY;
int move_dir[4][2] = {{0, -1}, {0, 1}, {-1, 0}, {1, 0}};

int nodeIndex(int r, int c) {
    if (r > 0 && r <= n && c > 0 && c <= n && maze_grid[r][c] != -1)
        return (r - 1) * n + c;
    return -1;
}

void setupGraph() {
    total_nodes = n * n;
    memset(graph_adj, -1, sizeof(graph_adj));
    for (int r1 = 1; r1 <= n; r1++) {
        for (int c1 = 1; c1 <= n; c1++) {
            if (maze_grid[r1][c1] == -1) continue;
            int p1 = (r1 - 1) * n + c1;
            graph_adj[p1][p1] = 0;
            for (int i = 0; i < 4; i++) {
                int r2 = r1 + move_dir[i][0];
                int c2 = c1 + move_dir[i][1];
                if (r2 > 0 && r2 <= n && c2 > 0 && c2 <= n && maze_grid[r2][c2] != -1) {
                    int p2 = (r2 - 1) * n + c2;
                    graph_adj[p1][p2] = 1;
                }
            }
        }
    }
}

int distArr[MAXN];
int queueArr[MAXM];

void computeDistances() {
    int front = 0, rear = 1;
    for (int i = 1; i <= total_nodes; i++) distArr[i] = INF;
    int startNode = (zr - 1) * n + zc;
    distArr[startNode] = 0;
    queueArr[0] = startNode;
    while (front < rear) {
        int u = queueArr[front++];
        for (int v = 1; v <= total_nodes; v++) {
            if (graph_adj[u][v] == 1 && distArr[v] > distArr[u] + 1) {
                distArr[v] = distArr[u] + 1;
                queueArr[rear++] = v;
            }
        }
    }
}

void computeAllPairs() {
    for (int k = 1; k <= total_nodes; k++) {
        for (int i = 1; i <= total_nodes; i++) {
            for (int j = 1; j <= total_nodes; j++) {
                if (graph_adj[i][k] != -1 && graph_adj[k][j] != -1) {
                    if (graph_adj[i][j] == -1 || graph_adj[i][j] > graph_adj[i][k] + graph_adj[k][j]) {
                        graph_adj[i][j] = graph_adj[i][k] + graph_adj[k][j];
                    }
                }
            }
        }
    }
}

struct EdgeFlow {
    int from, to, capacity, next;
};

vector<EdgeFlow> flowEdges;
int head[MAXN], edgeCount;
int sNode, tNode;

void addFlowEdge(int u, int v, int cap) {
    flowEdges.push_back({u, v, cap, head[u]});
    head[u] = (int)flowEdges.size() - 1;
    flowEdges.push_back({v, u, 0, head[v]});
    head[v] = (int)flowEdges.size() - 1;
}

int levelArr[MAXN];

bool buildLevel() {
    memset(levelArr, -1, sizeof(levelArr));
    levelArr[sNode] = 0;
    queue<int> q;
    q.push(sNode);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int i = head[u]; i != -1; i = flowEdges[i].next) {
            int v = flowEdges[i].to;
            if (flowEdges[i].capacity > 0 && levelArr[v] == -1) {
                levelArr[v] = levelArr[u] + 1;
                q.push(v);
            }
        }
    }
    return levelArr[tNode] != -1;
}

int ptrArr[MAXN];

int sendFlow(int u, int flow) {
    if (u == tNode) return flow;
    for (int &i = ptrArr[u]; i != -1; i = flowEdges[i].next) {
        int v = flowEdges[i].to;
        if (flowEdges[i].capacity > 0 && levelArr[v] == levelArr[u] + 1) {
            int pushed = sendFlow(v, min(flow, flowEdges[i].capacity));
            if (pushed > 0) {
                flowEdges[i].capacity -= pushed;
                flowEdges[i ^ 1].capacity += pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int computeMaxFlow() {
    int totalFlow = 0;
    while (buildLevel()) {
        for (int i = 0; i <= total_nodes + 1; i++) ptrArr[i] = head[i];
        while (int pushed = sendFlow(sNode, INF))
            totalFlow += pushed;
    }
    return totalFlow;
}

int solve() {
    maze_grid[zr][zc] = 0;
    setupGraph();
    computeDistances();
    maze_grid[zr][zc] = -1;
    setupGraph();
    computeAllPairs();
    flowEdges.clear();
    memset(head, -1, sizeof(head));
    edgeCount = 0;
    sNode = 0;
    tNode = cX + cY + 1;
    for (int i = 1; i <= cX; i++) {
        addFlowEdge(sNode, i, hu[i][2]);
    }
    for (int i = 1; i <= cY; i++) {
        addFlowEdge(cX + i, tNode, re[i][2]);
    }
    int p = (zr - 1) * n + zc;
    for (int i = 1; i <= cX; i++) {
        for (int j = 1; j <= cY; j++) {
            int p1 = (hu[i][0] - 1) * n + hu[i][1];
            int p2 = (re[j][0] - 1) * n + re[j][1];
            if (graph_adj[p1][p2] != -1 && graph_adj[p1][p2] <= t && graph_adj[p1][p2] < distArr[p2]) {
                addFlowEdge(i, cX + j, INF);
            } else if (graph_adj[p1][p2] != -1 && graph_adj[p1][p2] <= t && graph_adj[p1][p2] == distArr[p2]) {
                for (int z = 0; z < 4; z++) {
                    int rr = re[j][0] + move_dir[z][0];
                    int cc = re[j][1] + move_dir[z][1];
                    int pp = nodeIndex(rr, cc);
                    if (pp != -1) {
                        if (graph_adj[p1][pp] == graph_adj[p1][p2] - 1 && graph_adj[p1][pp] < distArr[pp]) {
                            addFlowEdge(i, cX + j, INF);
                        }
                    }
                }
            }
        }
    }
    return computeMaxFlow();
}

int main() {
    cin >> n >> t;
    cX = cY = 0;
    memset(maze_grid, 0, sizeof(maze_grid));
    for (int i = 1; i <= n; i++) {
        cin >> line_input;
        for (int j = 0; j < n; j++) {
            if (line_input[j] == 'Y') maze_grid[i][j + 1] = -1;
            else if (line_input[j] == 'Z') {
                zr = i; zc = j + 1;
                maze_grid[i][j + 1] = -1;
            } else if (line_input[j] > '0' && line_input[j] <= '9') {
                hu[++cX][0] = i;
                hu[cX][1] = j + 1;
                hu[cX][2] = line_input[j] - '0';
            }
        }
    }
    for (int i = 1; i <= n; i++) {
        cin >> line_input;
        for (int j = 0; j < n; j++) {
            if (line_input[j] > '0' && line_input[j] <= '9') {
                re[++cY][0] = i;
                re[cY][1] = j + 1;
                re[cY][2] = line_input[j] - '0';
            }
        }
    }
    cout << solve() << endl;
    return 0;
}
